def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A framed region's fill color depends on its interior dimensions.
    colors = {3: 8, 5: 4, 7: 3}

    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(grid[r1][c] == 2 for c in range(c1, c2 + 1)) and
                        all(grid[r2][c] == 2 for c in range(c1, c2 + 1)) and
                        all(grid[r][c1] == 2 for r in range(r1, r2 + 1)) and
                        all(grid[r][c2] == 2 for r in range(r1, r2 + 1))):
                        interior_h = r2 - r1 - 1
                        interior_w = c2 - c1 - 1
                        if interior_h == interior_w and interior_h in colors:
                            color = colors[interior_h]
                            for r in range(r1 + 1, r2):
                                for c in range(c1 + 1, c2):
                                    if grid[r][c] == 0:
                                        out[r][c] = color
    return out
